import os,glob,re, json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
filePath = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

grids = {}

with open(filePath, 'r') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
            if entry.get('type') == 'input':
                grid = entry.get('grid', [])
                task_id = entry.get('id', '')
                grids[task_id] = grid
            elif entry.get('type') == 'output':
                grid = entry.get('grid', [])
                task_id = entry.get('id', '')
            elif entry.get('type') == 'test_input':
                grid = entry.get('grid', [])
                task_id = entry.get('cid', '')
                grids[task_id] = grid
        except:
            pass

print("Keys in grids:", list(grids.keys())[:10])

